const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['index.html','styles.css','app.js','engine.js','panels.js','master-output.js','master-output-kernel.js','master-output-worklet.js','fx-tempo-capture-worklet.js','master-output-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
const click=s=>{assert($(s),'Missing '+s);$(s).click();},input=(s,v)=>{const e=$(s);assert(e,'Missing '+s);e.value=String(v);e.dispatchEvent(new Event('input',{bubbles:true}));};
async function until(fn,label){const end=performance.now()+20000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let n=0;n<bytes.length;n+=16384)s+=String.fromCharCode(...bytes.subarray(n,n+16384));return btoa(s);}
function metrics(a){let peak=0,squares=0;for(const v of a){assert(Number.isFinite(v),'Nonfinite captured output');peak=Math.max(peak,Math.abs(v));squares+=v*v;}return{peak,rms:Math.sqrt(squares/a.length),frames:a.length};}
let app;
function output(r){$('#master-original').textContent=JSON.stringify(r,null,2);const safe={...r,cases:r.cases.map(c=>({...c,captures:c.captures?.map(x=>({...x,base64:'Retained in original'}))})),recording:r.recording?{...r.recording,base64:'Retained in original'}:null};$('#master-results').textContent=JSON.stringify(safe,null,2);$('#master-status').textContent=r.completed?'Scoped master PCM, meter, limiter and reload checks passed':r.errors.length?'Failed: '+r.errors.map(e=>e.message).join('; '):'Recorded master audio; ready for reload';}
async function run(){
 const {state,engine}=app,r={startedAt:new Date().toISOString(),completed:false,scope:'Actual app master GUI, synthetic modifier events and MIDI-editor inputs. Independent post-output Float32 witness plus complete recording; independent sample limiter, not exact vendor/true-peak/native/physical acceptance.',criteria:{settlingSeconds:.9,captureSeconds:.3,meterDBTolerance:.08,outputRelativeRMSTolerance:.02,maximumLimitedSample:1.0000001,limitedRMSRange:[.65,.72]},cases:[],errors:[]},observers=[];$('#master-run').disabled=true;
 try{
  r.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical graph mute');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(()=>120),state.fxTempo);
  const sr=48000,duration=40,d=state.decks[0],b=engine.ctx.createBuffer(2,sr*duration,sr);for(let n=0;n<b.length;n++){b.getChannelData(0)[n]=.5*Math.sin(2*Math.PI*440*n/sr);b.getChannelData(1)[n]=-b.getChannelData(0)[n];}Object.assign(d.track,{bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:true,loopIn:0,loopOut:duration,slip:false,stemSlip:'off',sync:false,level:1,trim:1,low:0,mid:0,high:0,filter:0});engine.buffers.set(d.track.id,b);engine.mix(0,'level',1);engine.mix(0,'trim',1);for(const band of ['low','mid','high'])engine.mix(0,band,0);engine.setCross(0);
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);observers.push(split);const witnesses=[0,1].map(c=>{const node=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(node,c);node.connect(engine.ctx.destination);observers.push(node);return node;});
  const capture=(node,id)=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Output PCM capture timed out')),5000);node.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};node.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});});
  input('#master-level',0);click('[data-deck="0"][data-action="play"]');await until(()=>d.playing&&engine.masterSnapshot().ready,'Actual Play/master processor');await engine.recordStart();r.recordStart=engine.recordStarted;
  async function sample(name,db,limited,action,{silent=false}={}){
   $('#master-status').textContent='Running '+name;await action();await sleep(900);const at=engine.ctx.currentTime-engine.recordStarted,raw=await Promise.all(witnesses.map((node,c)=>capture(node,`${r.cases.length}-${c}`))),c={name,db,limited,silent,at,meter:engine.masterSnapshot(),ui:{level:Number($('#master-level').value),meter:Number($('#master-meter').value),warning:$('#master-limit').textContent},captures:[]};r.cases.push(c);
   for(const data of raw){const bytes=new Uint8Array(data.data.buffer);c.captures.push({...metrics(data.data),startFrame:data.startFrame,sha256:await hash(bytes),base64:base64(bytes)});}
   assert(c.ui.level===db&&c.meter.gainDB===db,'GUI and engine master level differ');assert(c.meter.invalid===0,'Unexpected invalid master input');
   if(silent){assert(c.captures.every(a=>a.peak<1e-6)&&c.meter.peak.every(v=>v<1e-6)&&!c.meter.limiting,'Stopped master must be silent and warning clear');}
   else{
    const prePeak=.5*10**(db/20),expectedDB=20*Math.log10(prePeak);c.expectedMeterDB=expectedDB;c.meterErrorDB=Math.abs(c.meter.displayDB-expectedDB);assert(c.meterErrorDB<=.08,'Stereo meter calibration failed');assert(c.meter.peak.every(p=>Math.abs(20*Math.log10(p)-expectedDB)<=.08),'Both antiphase channels must meter independently');assert(Math.abs(c.ui.meter-Math.max(-60,Math.min(9,c.meter.displayDB)))<.08,'Visible meter differs from actual snapshot');
    if(limited){assert(c.meter.limiting&&c.ui.warning==='LIMIT'&&c.meter.gainReductionDB>2.8&&c.meter.gainReductionDB<3.2,'Expected actual limiter warning/reduction');assert(c.captures.every(a=>a.peak<=1.0000001&&a.rms>.65&&a.rms<.72),'Independent PCM must be limited at full scale');}
    else{const expectedRMS=prePeak*10**(-3/20)/Math.SQRT2;c.expectedRMS=expectedRMS;c.relativeRMSErrors=c.captures.map(a=>Math.abs(a.rms/expectedRMS-1));assert(c.relativeRMSErrors.every(v=>v<=.02),'Unexpected attenuation/gain below limiter threshold');assert(!c.meter.limiting&&c.ui.warning!=='LIMIT','Limiter must release below threshold');}
   }c.passed=true;
  }
  await sample('neutral gain stereo baseline',0,false,async()=>{});await sample('GUI minus12',-12,false,async()=>input('#master-level',-12));await sample('GUI plus6',6,false,async()=>input('#master-level',6));await sample('GUI plus12 limiting',12,true,async()=>input('#master-level',12));
  await sample('Control-click resets0',0,false,async()=>$('#master-level').dispatchEvent(new MouseEvent('click',{bubbles:true,ctrlKey:true})));await sample('Alt-click sets3',3,false,async()=>$('#master-level').dispatchEvent(new MouseEvent('click',{bubbles:true,altKey:true})));
  click('[data-panel="midi"]');click('#midi-reset');for(const [number,encoding]of [[20,'7-bit absolute'],[21,'Relative two’s complement']]){for(const [id,v]of [['#midi-target','Master Output Level'],['#midi-type','CC'],['#midi-channel',3],['#midi-number',number],['#midi-encoding',encoding]])$(id).value=String(v);click('#midi-add');}
  const send=(number,value)=>{for(const [id,v]of [['#midi-type','CC'],['#midi-channel',3],['#midi-number',number],['#midi-test-value',value]])$(id).value=String(v);click('#midi-send');};
  await sample('MIDI maximum12 limiting',12,true,async()=>send(20,127));await sample('MIDI center0',0,false,async()=>send(20,64));await sample('MIDI minimum minus12',-12,false,async()=>send(20,0));await sample('MIDI relative plus tenth',-11.9,false,async()=>send(21,1));click('#modal-close');
  await sample('pause clears output and meter',-11.9,false,async()=>click('[data-deck="0"][data-action="play"]'),{silent:true});input('#master-level',3);r.savedDB=engine.masterDB;
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}
 finally{
  for(const d of state.decks)engine.pause(d);for(const n of observers)try{n.disconnect();}catch{}
  if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());r.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));r.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Expected stereo master');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');assert(r.cases.length===11&&r.cases.every(c=>c.passed),'Expected11 passing declared master cases');r.audioPassed=true;}catch(e){r.errors.push({message:e.message,stack:e.stack});}}
  r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.recordedAt=new Date().toISOString();output(r);sessionStorage.setItem('master-output-report',JSON.stringify(r));$('#master-reload').hidden=false;
 }
}
$('#master-run').onclick=run;$('#master-reload').onclick=()=>{sessionStorage.setItem('master-output-reload','yes');location.reload();};
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;
 if(sessionStorage.getItem('master-output-reload')==='yes'){sessionStorage.removeItem('master-output-reload');const r=JSON.parse(sessionStorage.getItem('master-output-report'));r.sourceReload=await identities();r.reload={db:app.engine.masterDB,preference:app.state.settings['Master Output Level'],slider:Number($('#master-level').value),stopped:app.state.decks.every(d=>!d.playing)};r.completed=r.audioPassed&&r.sourceStable&&JSON.stringify(r.sourceReload)===JSON.stringify(r.sourceBefore)&&r.reload.db===3&&r.reload.preference===3&&r.reload.slider===3&&r.reload.stopped&&!r.errors.length;r.finishedAt=new Date().toISOString();output(r);}
 else{$('#master-run').disabled=false;$('#master-status').textContent='Ready for one master output workflow';}}
boot().catch(e=>$('#master-status').textContent=e.message);
